const bodyTypesRussian = {
  "sedan": "Седан", "coupe": "Купе", "cabriolet": "Кабриолет", "wagon": "Универсал",
  "suv": "Внедорожник", "pickup": "Пикап", "limousine": "Лимузин", "hatchback": "Хэтчбек",
};

const CatalogPage = () => {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    brand: '',
    model: '',
    min_price: '',
    max_price: '',
    year_from: '',
    year_to: '',
    body_type: '',
    restyling: '',
  });
  const [showFilters, setShowFilters] = useState(window.innerWidth > 768);

  const fetchCars = async () => {
    setLoading(true);
    try {
      const params = {};
      Object.entries(filters).forEach(([key, value]) => {
        if (value !== '' && value !== null && value !== undefined) {
          params[key] = value;
        }
      });
      const res = await getCars(params);
      setCars(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCars();
  }, []); // загрузка при первом рендере

  const handleFilterChange = (field, value) => {
    setFilters(prev => ({ ...prev, [field]: value }));
  };

  const handleSubmitFilters = (e) => {
    e.preventDefault();
    fetchCars();
  };

  const handleResetFilters = () => {
    setFilters({
      brand: '', model: '', min_price: '', max_price: '',
      year_from: '', year_to: '', body_type: '', restyling: '',
    });
    // сразу загружаем все машины после сброса
    fetchCars();
  };

  const availableModels = filters.brand ? (brandModels[filters.brand] || []) : [];

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={styles.page}>
      <h1 className={styles.title}>Каталог автомобилей</h1>

      <button className={styles.filterToggle} onClick={() => setShowFilters(!showFilters)}>
        {showFilters ? 'Скрыть фильтры' : 'Показать фильтры'}
      </button>

      <div className={styles.content}>
        <AnimatePresence>
          {showFilters && (
            <motion.aside
              className={styles.sidebar}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
            >
              <form onSubmit={handleSubmitFilters} className={styles.filterForm}>
                <h3>Фильтры</h3>

                <div className={styles.filterGroup}>
                  <label>Марка</label>
                  <select
                    value={filters.brand}
                    onChange={(e) => {
                      handleFilterChange('brand', e.target.value);
                      handleFilterChange('model', '');
                    }}
                  >
                    <option value="">Все марки</option>
                    {Object.keys(brandModels).map(brand => (
                      <option key={brand} value={brand}>{brand}</option>
                    ))}
                  </select>
                </div>

                <div className={styles.filterGroup}>
                  <label>Модель</label>
                  <select
                    value={filters.model}
                    onChange={(e) => handleFilterChange('model', e.target.value)}
                    disabled={!filters.brand}
                  >
                    <option value="">Все модели</option>
                    {availableModels.map(model => (
                      <option key={model} value={model}>{model}</option>
                    ))}
                  </select>
                </div>

                <div className={styles.filterGroup}>
                  <label>Цена, ₽</label>
                  <div className={styles.priceInputs}>
                    <input type="number" placeholder="от" value={filters.min_price}
                      onChange={(e) => handleFilterChange('min_price', e.target.value)} />
                    <input type="number" placeholder="до" value={filters.max_price}
                      onChange={(e) => handleFilterChange('max_price', e.target.value)} />
                  </div>
                </div>

                <div className={styles.filterGroup}>
                  <label>Год выпуска</label>
                  <div className={styles.priceInputs}>
                    <input type="number" placeholder="от" value={filters.year_from}
                      onChange={(e) => handleFilterChange('year_from', e.target.value)} />
                    <input type="number" placeholder="до" value={filters.year_to}
                      onChange={(e) => handleFilterChange('year_to', e.target.value)} />
                  </div>
                </div>

                <div className={styles.filterGroup}>
                  <label>Тип кузова</label>
                  <select value={filters.body_type}
                    onChange={(e) => handleFilterChange('body_type', e.target.value)}>
                    <option value="">Все типы</option>
                    {Object.entries(bodyTypesRussian).map(([key, label]) => (
                      <option key={key} value={key}>{label}</option>
                    ))}
                  </select>
                </div>

                <div className={styles.filterGroup}>
                  <label>Рестайлинг</label>
                  <select value={filters.restyling}
                    onChange={(e) => handleFilterChange('restyling', e.target.value)}>
                    <option value="">Не важно</option>
                    <option value="true">Да</option>
                    <option value="false">Нет</option>
                  </select>
                </div>

                <div className={styles.filterActions}>
                  <button type="submit" className={styles.applyBtn}>Применить</button>
                  <button type="button" className={styles.resetBtn} onClick={handleResetFilters}>Сбросить</button>
                </div>
              </form>
            </motion.aside>
          )}
        </AnimatePresence>

        <div className={styles.catalogGrid}>
          {loading ? (
            <p className={styles.loading}>Загрузка...</p>
          ) : cars.length === 0 ? (
            <p className={styles.noResults}>По вашему запросу ничего не найдено</p>
          ) : (
            <>
              <p className={styles.resultCount}>Найдено: {cars.length}</p>
              <div className={styles.grid}>
                {cars.map((car) => (
                  <motion.div
                    key={car.id}
                    whileHover={{ scale: 1.03, zIndex: 10 }}
                    initial={{ opacity: 0, y: 30 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4 }}
                    style={{ perspective: 1000 }}
                  >
                    <Link to={`/cars/${car.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
                      <div className={styles.card}>
                        <img
                          src={getImageUrl(car.image_url || '/images/default-car.jpg')}
                          alt={car.model}
                          className={styles.cardImage}
                        />
                        <div className={styles.cardBody}>
                          <h3>{car.brand} {car.model}</h3>
                          <p className={styles.carYear}>{car.year} год</p>
                          <p className={styles.carPrice}>{car.price.toLocaleString()} ₽</p>
                        </div>
                      </div>
                    </Link>
                  </motion.div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </motion.div>
  );
};

export default CatalogPage;
